10	export function Providers({ children }: { children: React.ReactNode }) {
11	  const [queryClient] = useState(
12	    () =>
13	      new QueryClient({
14	        defaultOptions: {
15	          queries: {
16	            staleTime: 5 * 60 * 1000,
17	            gcTime: 10 * 60 * 1000,
18	            refetchOnWindowFocus: false,
19	            refetchOnMount: false,
20	            retry: 1,
21	          },
22	        },
23	      }),
24	  );
25	
26	  return (
27	    <QueryClientProvider client={queryClient}>
28	      <ThemeProvider
29	        attribute="class"
30	        defaultTheme="light"
31	        storageKey="rankora-theme"
32	      >
33	        <AuthProvider>
34	          <TooltipProvider>
35	            {children}
36	            <Sonner />
37	          </TooltipProvider>
38	        </AuthProvider>
39	      </ThemeProvider>
40	    </QueryClientProvider>
41	  );
42	}
